#include <iostream>
#include <map>
#include <string>
// 공백으로 나눈 토큰 전체를 검사합니다. 숫자 사이의 붙은 부호는 허용하지 않습니다.
template <typename T>
bool ReadInteger(T& result, long long low, long long high) {
    std::string token;
    if (!(std::cin >> token)) return false;
    std::size_t pos = 0;
    bool negative = false;
    if (token[pos] == '+' || token[pos] == '-') {
        negative = token[pos] == '-';
        if (++pos == token.size()) return false;
    }
    const long long bound = (-low > high) ? -low : high;
    long long magnitude = 0;
    for (; pos < token.size(); ++pos) {
        if (token[pos] < '0' || token[pos] > '9') return false;
        const int digit = token[pos] - '0';
        if (digit > bound || magnitude > (bound - digit) / 10) return false;
        magnitude = magnitude * 10 + digit;
    }
    const long long value = negative ? -magnitude : magnitude;
    if (value < low || value > high) return false;
    result = static_cast<T>(value);
    return true;
}
int main() {
    int n; long long target;
    if (!ReadInteger(n, 0, 2000) || !ReadInteger(target, -1000000, 1000000)) return 1;
    std::map<long long, long long> freq;
    for (int i = 0; i < n; ++i) {
        long long x;
        if (!ReadInteger(x, -1000000, 1000000)) return 1;
        ++freq[x];
    }
    std::string extra;
    if (std::cin >> extra) return 1;
    long long answer = 0;
    for (const auto& entry : freq) {
        const long long x = entry.first, f = entry.second;
        const long long y = target - x;
        if (x > y) continue; // 같은 무순서 값쌍을 두 번 세지 않습니다.
        const auto other = freq.find(y);
        if (other == freq.end()) continue;
        if (x < y) answer += f * other->second;
        else answer += f * (f - 1) / 2; // 같은 값의 서로 다른 두 위치입니다.
    }
    std::cout << answer << '\n';
}
